/// Build a plausible main-room-correction filter.
fn main_filter(freq: f64, q: f64, gain_db: f64) -> EQFilter {
    EQFilter::new(BiquadFilterType::Peak, freq, q, gain_db)
}

/// Build a plausible broadband pre-correction filter. We use distinct
/// frequencies from `main_filter` so test assertions can tell the two
/// EQs apart by inspecting their filter lists.
fn bb_filter(freq: f64, q: f64, gain_db: f64) -> EQFilter {
    EQFilter::new(BiquadFilterType::Lowshelf, freq, q, gain_db)
}

/// Collect all user-facing EQ plugins from the graph with their names.
fn eq_plugins_with_names(graph: &PluginGraph) -> Vec<(Option<String>, PluginSettings)> {
    graph
        .plugins()
        .iter()
        .filter(|p| matches!(p.plugin_type(), PluginType::EQ))
        .filter(|p| !p.permanent) // exclude any permanent/fixture EQs
        .map(|p| (p.name.clone(), p.settings.clone()))
        .collect()
}

fn named_eq<'a>(graph: &'a PluginGraph, name: &str) -> Option<&'a sotf_audio_player::Plugin> {
    graph
        .plugins()
        .into_iter()
        .find(|p| p.name.as_deref() == Some(name))
}

/// The core regression: applying optimizer output that has both broadband
/// and main filters must produce **two** distinct EQ plugins with the
/// user-facing names "Broadband EQ" and "Room EQ".
#[test]
fn apply_broadband_plus_main_produces_two_named_eqs() {
    let mut graph = PluginGraph::with_default_rack();

    let bb = vec![bb_filter(60.0, 0.7, 3.0)];
    let main = vec![main_filter(120.0, 1.2, -2.5), main_filter(800.0, 2.0, -1.5)];
    let per_channel_bb = vec![bb.clone(), bb.clone()];
    let per_channel_main = vec![main.clone(), main.clone()];

    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb,
        &per_channel_bb,
        bb.len() * 2,
        &main,
        &per_channel_main,
    );

    let eqs = eq_plugins_with_names(&graph);
    assert_eq!(
        eqs.len(),
        2,
        "Expected exactly 2 EQ plugins (broadband + main), got {}. \
         This is the Issue-6 regression: the apply-to-rack flow is \
         merging the two stages into one. EQs found: {:?}",
        eqs.len(),
        eqs.iter().map(|(n, _)| n.clone()).collect::<Vec<_>>(),
    );

    // Names must be the user-facing contract.
    let names: Vec<Option<String>> = eqs.iter().map(|(n, _)| n.clone()).collect();
    assert!(
        names.iter().any(|n| n.as_deref() == Some("Broadband EQ")),
        "Expected a plugin named 'Broadband EQ'. Names: {:?}",
        names
    );
    assert!(
        names.iter().any(|n| n.as_deref() == Some("Room EQ")),
        "Expected a plugin named 'Room EQ'. Names: {:?}",
        names
    );
}

/// Each plugin must carry the correct filter set — a second regression
/// guard so a future bug can't "pass" the count check by creating two
/// identical EQs.
#[test]
fn apply_broadband_and_main_carry_distinct_filters() {
    let mut graph = PluginGraph::with_default_rack();

    let bb = vec![bb_filter(55.0, 0.7, 4.5)];
    let main = vec![main_filter(250.0, 1.0, -3.0)];
    let per_channel_bb = vec![bb.clone(), bb.clone()];
    let per_channel_main = vec![main.clone(), main.clone()];

    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb,
        &per_channel_bb,
        bb.len() * 2,
        &main,
        &per_channel_main,
    );

    let broadband = named_eq(&graph, "Broadband EQ").expect("Broadband EQ missing");
    let room_eq = named_eq(&graph, "Room EQ").expect("Room EQ missing");

    let PluginSettings::EQ {
        filters: bb_filters,
        max_filters: bb_max,
        per_channel_mode: bb_pcm,
        ..
    } = &broadband.settings
    else {
        panic!("Broadband EQ has wrong settings variant");
    };
    assert_eq!(bb_filters.len(), 1, "Broadband filter count mismatch");
    assert!((bb_filters[0].frequency - 55.0).abs() < f64::EPSILON);
    assert_eq!(*bb_max, 4, "Broadband max_filters must be 4");
    assert!(*bb_pcm, "Broadband must run in per-channel mode");

    let PluginSettings::EQ {
        filters: main_filters,
        max_filters: main_max,
        per_channel_mode: main_pcm,
        ..
    } = &room_eq.settings
    else {
        panic!("Room EQ has wrong settings variant");
    };
    assert_eq!(main_filters.len(), 1, "Main filter count mismatch");
    assert!((main_filters[0].frequency - 250.0).abs() < f64::EPSILON);
    assert_eq!(*main_max, 10, "Room EQ max_filters must be 10");
    assert!(*main_pcm, "Room EQ must run in per-channel mode");
}

/// Chain ordering: broadband pre-correction must sit BEFORE the main
/// room EQ, otherwise the main-band filters would be fed non-equalised
/// bass and miss their operating point.
#[test]
fn broadband_eq_is_positioned_before_main_eq() {
    let mut graph = PluginGraph::with_default_rack();

    let bb = vec![bb_filter(60.0, 0.7, 3.0)];
    let main = vec![main_filter(120.0, 1.2, -2.5)];
    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb,
        &[bb.clone(), bb.clone()],
        bb.len() * 2,
        &main,
        &[main.clone(), main.clone()],
    );

    let bb_idx = graph
        .find_plugin_index_by_name("Broadband EQ")
        .expect("Broadband EQ missing from linear chain");
    let main_idx = graph
        .find_plugin_index_by_name("Room EQ")
        .expect("Room EQ missing from linear chain");

    assert!(
        bb_idx < main_idx,
        "Broadband EQ (idx {}) must come before Room EQ (idx {}) in the chain",
        bb_idx,
        main_idx,
    );
}

/// Second Apply with the same names is idempotent: we must UPDATE the
/// existing plugins in place, not pile up fresh copies each run. This
/// is the behavior a user expects when re-running the optimizer.
#[test]
fn second_apply_is_idempotent() {
    let mut graph = PluginGraph::with_default_rack();

    let bb = vec![bb_filter(60.0, 0.7, 3.0)];
    let main = vec![main_filter(120.0, 1.2, -2.5)];

    // First apply
    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb,
        &[bb.clone(), bb.clone()],
        bb.len() * 2,
        &main,
        &[main.clone(), main.clone()],
    );
    assert_eq!(
        eq_plugins_with_names(&graph).len(),
        2,
        "First apply should produce 2 EQs"
    );

    // Second apply with fresh filter values — should UPDATE, not add.
    let bb2 = vec![bb_filter(70.0, 0.8, 4.0)];
    let main2 = vec![main_filter(300.0, 1.5, -4.0)];
    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb2,
        &[bb2.clone(), bb2.clone()],
        bb2.len() * 2,
        &main2,
        &[main2.clone(), main2.clone()],
    );

    let eqs = eq_plugins_with_names(&graph);
    assert_eq!(
        eqs.len(),
        2,
        "Second apply must be idempotent — expected 2 EQs, got {}. \
         Re-applying Room EQ is duplicating plugins.",
        eqs.len()
    );

    // Verify the values were actually refreshed (not left at first-apply state).
    let room = named_eq(&graph, "Room EQ").unwrap();
    if let PluginSettings::EQ { filters, .. } = &room.settings {
        assert!(
            (filters[0].frequency - 300.0).abs() < f64::EPSILON,
            "Room EQ filters were not updated on second apply; freq={}",
            filters[0].frequency
        );
    } else {
        panic!("Room EQ settings have wrong variant");
    }
}

/// Upgrade path: a user running the OLD single-EQ "Apply to Rack" will
/// have an unnamed user EQ in their rack. Running the new flow must
/// adopt that existing plugin as "Room EQ" rather than leaving it as a
/// stale sibling of the new plugin.
#[test]
fn preexisting_unnamed_eq_is_adopted_as_room_eq() {
    let mut graph = PluginGraph::with_default_rack();
    // Simulate an upgrade: older build left behind an unnamed user EQ.
    graph.add_user_plugin(&PluginType::EQ).unwrap();
    let anon_count_before = graph
        .plugins()
        .iter()
        .filter(|p| {
            matches!(p.plugin_type(), PluginType::EQ)
                && !p.permanent
                && p.name.as_deref().unwrap_or("").is_empty()
        })
        .count();
    assert_eq!(
        anon_count_before, 1,
        "Test fixture should have exactly 1 pre-existing unnamed EQ"
    );

    // Apply the new flow with broadband + main.
    let bb = vec![bb_filter(60.0, 0.7, 3.0)];
    let main = vec![main_filter(120.0, 1.2, -2.5)];
    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &bb,
        &[bb.clone(), bb.clone()],
        bb.len() * 2,
        &main,
        &[main.clone(), main.clone()],
    );

    // No anonymous EQ should remain — the old one must have been
    // renamed to "Room EQ" (or replaced in-place).
    let anon_count_after = graph
        .plugins()
        .iter()
        .filter(|p| {
            matches!(p.plugin_type(), PluginType::EQ)
                && !p.permanent
                && p.name.as_deref().unwrap_or("").is_empty()
        })
        .count();
    assert_eq!(
        anon_count_after, 0,
        "Pre-existing anonymous EQ must be adopted (renamed), not left orphaned. \
         Found {} anonymous EQ(s) after apply.",
        anon_count_after
    );

    // Still only 2 EQs total, with both expected names.
    let eqs = eq_plugins_with_names(&graph);
    assert_eq!(
        eqs.len(),
        2,
        "Expected 2 named EQs after adopting the pre-existing one, got {}. \
         Names: {:?}",
        eqs.len(),
        eqs.iter().map(|(n, _)| n.clone()).collect::<Vec<_>>()
    );
    assert!(named_eq(&graph, "Broadband EQ").is_some());
    assert!(named_eq(&graph, "Room EQ").is_some());
}

