/// Demonstrates the OLD buggy behavior is actually buggy: the merge-style
/// `simulate_save_to_rack` helper (from `room_eq_config_tests.rs`) only
/// ever creates ONE EQ, so there's no way to tell broadband from main.
/// This is the "before" snapshot; the fix must produce the "after"
/// behavior verified by the other tests in this file.
#[test]
fn old_merge_style_apply_loses_the_two_eq_distinction() {
    // Build a graph using the old merge-style logic inline (mirrors the
    // pre-fix behavior that shipped and caused Issue 6):
    let mut graph = PluginGraph::with_default_rack();

    let bb = vec![bb_filter(60.0, 0.7, 3.0)];
    let main = vec![main_filter(120.0, 1.2, -2.5)];

    // OLD behavior: merge both stages into one un-named EQ.
    let mut merged = main.clone();
    merged.extend(bb.clone());
    let merged_per_ch = vec![merged.clone(), merged.clone()];
    let settings = PluginSettings::EQ {
        channels: 2,
        filters: merged.clone(),
        channel_filters: Some(merged_per_ch),
        per_channel_mode: true,
        max_filters: 10,
        tdf2: false,
        topology: 0.0,
    };
    let insert_idx = graph.user_plugin_insert_index();
    let node_id = graph.insert_plugin(insert_idx, &PluginType::EQ).unwrap();
    graph.nodes.get_mut(&node_id).unwrap().plugin.settings = settings;
    // NOTE: no name assigned — this is the pre-fix state.

    let eqs = eq_plugins_with_names(&graph);
    // The old behavior only produces 1 EQ, *without* the named stages,
    // which is exactly the reported bug.
    assert_eq!(
        eqs.len(),
        1,
        "Sanity check on the old buggy behavior — it produced a single merged EQ"
    );
    assert!(
        eqs[0].0.is_none(),
        "Old buggy behavior left the EQ anonymous"
    );
}

/// Convert an autoeq `PluginConfigWrapper` into the sotf-player
/// `DspPluginConfig` shape. They are structurally identical — both
/// `(String, serde_json::Value)` — so this is a field-by-field copy.
fn to_dsp_plugin(w: &autoeq::roomeq::PluginConfigWrapper) -> DspPluginConfig {
    DspPluginConfig {
        plugin_type: w.plugin_type.clone(),
        parameters: w.parameters.clone(),
    }
}

/// Build a `ChannelDspChain` mirroring what the optimizer writes into
/// `DspChainOutput` for a single channel:
///
/// 1. One broadband EQ plugin from `create_alignment_plugins` (labeled
///    "broadband" — this is the bit that regressed to unlabeled).
/// 2. One main-EQ plugin from `create_eq_plugin` (unlabeled).
fn build_channel_dsp_from_real_emitters(
    channel_name: &str,
    lowshelf_db: f64,
    highshelf_db: f64,
    main_filters: &[Biquad],
) -> ChannelDspChain {
    const SAMPLE_RATE: f64 = 48_000.0;

    let align = SpectralAlignmentResult {
        lowshelf_gain_db: lowshelf_db,
        highshelf_gain_db: highshelf_db,
        flat_gain_db: 0.0,
        residual_rms_db: 0.0,
    };
    let (bb_plugin, _gain_plugin) = create_alignment_plugins(&align, SAMPLE_RATE);

    let mut plugins: Vec<DspPluginConfig> = Vec::new();
    if let Some(bb) = bb_plugin {
        plugins.push(to_dsp_plugin(&bb));
    }
    plugins.push(to_dsp_plugin(&create_eq_plugin(main_filters)));

    ChannelDspChain {
        channel: channel_name.to_string(),
        plugins,
        drivers: None,
        initial_curve: None,
        final_curve: None,
        eq_response: None,
        target_curve: None,
        pre_ir: None,
        post_ir: None,
        fir_temporal_masking: None,
        direct_early_late_correction: None,
    }
}

/// End-to-end: feed a `ChannelDspChain` whose plugins come from the real
/// autoeq emitters into the classifier. Broadband shelves must land in
/// the bb bucket, and main peaks must land in the main bucket. If the
/// emitter ever regresses to unlabeled broadband, the main bucket will
/// swell to 3 filters and this test fails loudly.
#[test]
fn classify_real_emitter_output_separates_broadband_from_main() {
    let main = vec![
        Biquad::new(AutoeqBiquadFilterType::Peak, 120.0, 48_000.0, 1.2, -2.5),
        Biquad::new(AutoeqBiquadFilterType::Peak, 800.0, 48_000.0, 2.0, -1.5),
    ];
    let channel = build_channel_dsp_from_real_emitters("FL", 3.0, -2.0, &main);

    // Sanity: the channel has two EQ plugins. If this ever drops to one,
    // the upstream emitter changed and the assertion below would be
    // vacuous — so lock the fixture shape too.
    let eq_plugin_count = channel
        .plugins
        .iter()
        .filter(|p| p.plugin_type.eq_ignore_ascii_case("eq"))
        .count();
    assert_eq!(
        eq_plugin_count, 2,
        "Fixture should have 2 EQ plugins (broadband + main); got {}",
        eq_plugin_count
    );

    let (main_filters, bb_filters) = classify_channel_eq_filters(&channel);

    assert_eq!(
        bb_filters.len(),
        2,
        "Expected 2 broadband shelves (low + high); got {}. \
         This fails if `create_alignment_plugins` emits unlabeled broadband \
         EQ — the Issue-6 root cause.",
        bb_filters.len()
    );
    assert_eq!(
        main_filters.len(),
        2,
        "Expected 2 main peak filters; got {}. A too-high count here \
         means broadband shelves leaked into the main bucket because \
         the 'broadband' label was missing from the emitter.",
        main_filters.len()
    );

    // Additional shape check: broadband filters must be shelves, not peaks.
    for bb in &bb_filters {
        assert!(
            matches!(
                bb.filter_type,
                BiquadFilterType::Lowshelf | BiquadFilterType::Highshelf
            ),
            "Broadband bucket should only contain shelves; got {:?}",
            bb.filter_type
        );
    }
}

/// End-to-end pipeline: real emitter output → classify → upsert must
/// produce the two named EQ plugins the user expects. This is the
/// exact sequence `apply_room_eq_to_player` runs in production.
#[test]
fn real_emitter_output_flows_to_two_named_eq_plugins() {
    let main = vec![Biquad::new(
        AutoeqBiquadFilterType::Peak,
        250.0,
        48_000.0,
        1.0,
        -3.0,
    )];
    let ch_fl = build_channel_dsp_from_real_emitters("FL", 3.0, -2.0, &main);
    let ch_fr = build_channel_dsp_from_real_emitters("FR", 3.0, -2.0, &main);

    let (fl_main, fl_bb) = classify_channel_eq_filters(&ch_fl);
    let (fr_main, fr_bb) = classify_channel_eq_filters(&ch_fr);

    // Mirror the exact aggregation apply_room_eq_to_player does.
    let per_channel_bb = vec![fl_bb.clone(), fr_bb.clone()];
    let per_channel_main = vec![fl_main.clone(), fr_main.clone()];
    let total_bb: usize = per_channel_bb.iter().map(|f| f.len()).sum();
    let global_bb = per_channel_bb.first().cloned().unwrap_or_default();
    let global_main = per_channel_main.first().cloned().unwrap_or_default();

    assert!(
        total_bb > 0,
        "total_bb must be non-zero — otherwise upsert skips the Broadband EQ \
         and we regress to a single merged EQ (Issue 6)."
    );

    let mut graph = PluginGraph::with_default_rack();
    upsert_named_room_eq_plugins(
        &mut graph,
        2,
        &global_bb,
        &per_channel_bb,
        total_bb,
        &global_main,
        &per_channel_main,
    );

    let eqs = eq_plugins_with_names(&graph);
    assert_eq!(
        eqs.len(),
        2,
        "End-to-end flow must produce 2 named EQs from real emitter \
         output; got {}. Names: {:?}",
        eqs.len(),
        eqs.iter().map(|(n, _)| n.clone()).collect::<Vec<_>>()
    );
    assert!(named_eq(&graph, "Broadband EQ").is_some());
    assert!(named_eq(&graph, "Room EQ").is_some());
}

/// If the optimizer produces no alignment corrections (both shelf gains
/// below the `MIN_CORRECTION_DB` threshold), `create_alignment_plugins`
/// returns `None` for the EQ plugin. The classifier must then route the
/// single main plugin entirely to the main bucket — and the rack must
/// end up with only one named EQ.
#[test]
fn classifier_handles_missing_broadband_plugin() {
    let main = vec![Biquad::new(
        AutoeqBiquadFilterType::Peak,
        120.0,
        48_000.0,
        1.2,
        -2.5,
    )];
    // 0.1 dB is below MIN_CORRECTION_DB (0.3), so create_alignment_plugins
    // will return (None, None) — no broadband EQ plugin at all.
    let channel = build_channel_dsp_from_real_emitters("FL", 0.1, -0.1, &main);

    let eq_plugin_count = channel
        .plugins
        .iter()
        .filter(|p| p.plugin_type.eq_ignore_ascii_case("eq"))
        .count();
    assert_eq!(
        eq_plugin_count, 1,
        "With corrections below threshold, only the main EQ plugin should \
         be emitted; got {} EQ plugins",
        eq_plugin_count
    );

    let (main_filters, bb_filters) = classify_channel_eq_filters(&channel);
    assert_eq!(main_filters.len(), 1);
    assert!(
        bb_filters.is_empty(),
        "Without broadband emission the bb bucket must be empty"
    );
}

